"""Native single-repository staging for the Python gr2 CLI."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path, PurePosixPath

from .gitops import git, run


class AddError(Exception):
    pass


@dataclass(frozen=True)
class AddResult:
    requested_paths: tuple[str, ...]
    staged_files: tuple[str, ...]
    skipped_bytecode: tuple[str, ...] = ()


def is_bytecode(path: str) -> bool:
    """Python bytecode: anything under a ``__pycache__`` directory, or a ``.pyc`` / ``.pyo`` file. Generated by
    every import and test run, never authored, and a stale one can be imported in place of its source."""
    p = PurePosixPath(path)
    return "__pycache__" in p.parts[:-1] or p.suffix in (".pyc", ".pyo")


def _untracked_bytecode(repo: Path, requested: tuple[str, ...]) -> tuple[str, ...]:
    """The untracked, not-ignored bytecode under the requested pathspecs: what ``add --all`` would newly stage."""
    try:
        listed = git(repo, "ls-files", "--others", "--exclude-standard", "-z", "--", *requested)
    except OSError as exc:
        raise AddError(f"failed to list untracked files in {repo}: {exc}") from exc
    if listed.returncode != 0:
        detail = (listed.stderr or listed.stdout).strip()
        raise AddError(detail or f"git ls-files failed with exit {listed.returncode}")
    return tuple(sorted(name for name in listed.stdout.split("\0") if name and is_bytecode(name)))


def stage_files(repo: Path, paths: list[str], *, include_bytecode: bool = False) -> AddResult:
    """Stage only the requested pathspecs and report their observed index rows.

    ``git add --all`` is deliberate. A deleted tracked path does not exist on
    disk, so a filesystem existence precheck turns a valid deletion into a
    false "missing" error. Git's index is the authority for pathspec validity.

    Untracked Python bytecode is skipped unless ``include_bytecode``: git's own ignore set still applies first, and
    this one built-in rule covers a repo that ignores nothing. It is read BEFORE the add (only files that were
    untracked) and taken back out of the index after it, so tracked bytecode stages exactly as git stages it, a
    change or a delete alike, and the add keeps git's own pathspec errors.
    """
    if not paths:
        raise AddError("at least one path is required")

    requested = tuple(paths)
    skipped = () if include_bytecode else _untracked_bytecode(repo, requested)
    try:
        staged = git(repo, "add", "--all", "--", *requested)
    except OSError as exc:
        raise AddError(f"failed to launch git add in {repo}: {exc}") from exc
    if staged.returncode != 0:
        detail = (staged.stderr or staged.stdout).strip()
        raise AddError(detail or f"git add failed with exit {staged.returncode}")

    if skipped:
        # Literal pathspecs on stdin: a name with a glob character is that file, and a long list never meets argv.
        spec = "".join(f":(literal){name}\0" for name in skipped)
        try:
            unstaged = run(repo, "rm", "--cached", "--quiet", "--ignore-unmatch", "--pathspec-from-file=-",
                           "--pathspec-file-nul", input=spec, via_cwd=True)
        except OSError as exc:
            raise AddError(f"git add staged untracked bytecode and it could not be unstaged: {exc}") from exc
        if unstaged.returncode != 0:
            detail = (unstaged.stderr or unstaged.stdout).strip()
            raise AddError(f"git add staged untracked bytecode and it could not be unstaged: {detail}")

    try:
        observed = git(repo, "diff", "--cached", "--name-only", "-z", "--", *requested)
    except OSError as exc:
        raise AddError(
            f"git add succeeded but staged-path evidence was unavailable: {exc}"
        ) from exc
    if observed.returncode != 0:
        detail = (observed.stderr or observed.stdout).strip()
        raise AddError(detail or "git add succeeded but staged-path evidence was unavailable")

    staged_files = tuple(sorted(name for name in observed.stdout.split("\0") if name))
    return AddResult(requested_paths=requested, staged_files=staged_files, skipped_bytecode=skipped)


def skip_line(skipped: tuple[str, ...]) -> str:
    """The one line `add` prints when it skipped bytecode: a count and one example path."""
    return (f"Skipped {len(skipped)} untracked bytecode path(s) (__pycache__/, *.pyc, *.pyo), e.g. {skipped[0]}; "
            "pass --include-bytecode to stage them")
